func:
const t = msg.payload;
msg.payload = {battery: t.battery ?? 1, queue: t.queue ?? 0, rtt_ms: t.rtt_ms ?? 20, bandwidth_mbps: t.bandwidth_mbps ?? 20, arrivals: t.arrivals ?? 0, edge_load: t.edge_load ?? flow.get('edge_load') ?? 0.3};
msg.headers = {'Content-Type': 'application/json'};
return msg;

const d = msg.payload;
const where = d.placement === 'edge' ? `edge, share ${d.edge_share}` : 'local';
node.status({fill: d.rejected ? 'yellow' : (d.placement === 'edge' ? 'blue' : 'green'), shape: 'dot', text: `${d.model} @ ${d.rate_fps} fps (${where})${d.rejected ? ' - offload rejected' : ''}`});
return null;

const k = msg.payload.kpis, l = msg.payload.last;
flow.set('edge_load', l.edge_load);
msg.payload = {t: k.t, battery: k.battery, mean_accuracy: k.mean_accuracy, violation_rate: k.violation_rate, energy_j: k.energy_j, processed: k.processed, dropped: k.dropped, edge_cost: k.edge_cost, tier: l.tier, where: l.where, edge_accepting: l.edge_accepting, latency_ms: +l.latency_ms.toFixed(1)};
node.status({fill: 'grey', shape: 'ring', text: `t=${k.t}s acc ${k.mean_accuracy} viol ${k.violation_rate} battery ${k.battery}`});
return msg;
